#!/usr/bin/env bash
# probe_D453.sh — проба пункта D453: журнал и счётчик циклов `hooks/rework-detector.sh`
#                 ключевались одним `session_id`, общим у родителя и субагента, поэтому
#                 правка→прогон→правка родителя и ПЕРВАЯ правка субагента считались одной
#                 цепочкой. Вторая половина: `resolve_actor_id` звался только внутри
#                 `rw_world_targets`, а та — только в ветке `Bash`, и у `Edit|Write|MultiEdit`
#                 актор не резолвился вовсе.
# Результат: журнал, снимок мира и повод принадлежат АКТОРУ на ВСЕХ инструментах; первая
#            правка субагента не получает «третий заход» родителя; повод субагента не лежит
#            в файле, который читает родитель.
# Проверка результата: bash hooks/tests/fixtures/probe_D453.sh даёт 0
#
# Коды: 0 — желаемое поведение соблюдено; 1 — дефект наблюдён; 2 — рамка не собралась.
#
# РОД M ПРОВЕРЕН И НЕ ПОДТВЕРЖДЁН (18 сентября 2026). Признак рода указывает сюда, потому
# что песочница строится голым `mktemp -d`, а в детекторе есть отбрасывание путей `*/tmp/*`
# — на macOS `mktemp` даёт `/var/folders/…`, и класс был бы невидим до раннера. Замер на
# ОБОИХ корнях: с песочницей, принудительно созданной под `/tmp`
# (`mktemp -d /tmp/probeM.XXXXXX`), коды те же, что и с обычной.
# ПОЧЕМУ отбрасывание сюда не достаёт — прочитано у источника, а не выведено из поведения:
# `case … */tmp/*) continue` стоит внутри `rw_write_targets` (`rework-detector.sh:185`), то
# есть применяется к целям, извлечённым из ТЕКСТА КОМАНДЫ. У `rw_world_targets` фильтра по
# пути нет ни одного: он читает `git status --porcelain` ОТНОСИТЕЛЬНО корня репозитория, и
# пути там относительные — `f.sh`, а не `/tmp/…/f.sh`. Песочница целиком лежит внутри
# своего git-репозитория, поэтому её собственный абсолютный путь в сравнение не попадает.
# НАЗВАННЫЙ ПРЕДЕЛ замера: он сделан на macOS с ПОДСТАВЛЕННЫМ корнем песочницы, а не на
# Linux, где `/tmp` — умолчание. Условие снятия: тот же замер в контейнере раннера.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/../../.." && pwd -P)"
MECH="${CLAUDSOUL_REPO:-$ROOT}"
HOOK="$MECH/hooks/rework-detector.sh"
[ -f "$HOOK" ] || { echo "probe_D453: нет $HOOK" >&2; exit 2; }
command -v jq >/dev/null 2>&1 || { echo "probe_D453: нет jq" >&2; exit 2; }
command -v git >/dev/null 2>&1 || { echo "probe_D453: нет git" >&2; exit 2; }
T=$(cd "$(mktemp -d)" && pwd -P) || { echo "probe_D453: нет временного каталога" >&2; exit 2; }
trap 'rm -rf "$T"' EXIT
S="$T/state"; mkdir -p "$S" "$T/repo"
( cd "$T/repo" && git init -q . && printf 'x\n' > f.sh && git add -A \
  && git -c user.email=p@p -c user.name=p commit -qm init ) >/dev/null 2>&1 \
  || { echo "probe_D453: репозиторий не собрался" >&2; exit 2; }

SID=d453
call() {  # call <команда|""> <файл|""> [agent_id]
    jq -cn --arg s "$SID" --arg c "$1" --arg f "$2" --arg a "${3:-}" --arg w "$T/repo" \
        '{session_id:$s, cwd:$w}
         + (if $c == "" then {tool_name:"Edit", tool_input:{file_path:$f}}
            else {tool_name:"Bash", tool_input:{command:$c}} end)
         + (if $a == "" then {} else {agent_id:$a, agent_type:"general-purpose"} end)' \
      | env STATE_DIR="$S" bash "$HOOK" 2>/dev/null
}
F="$T/repo/f.sh"

# Три цикла родителя: правка → прогон → правка → прогон → правка.
call "" "$F" >/dev/null; call "bash t.sh" "" >/dev/null
call "" "$F" >/dev/null; call "bash t.sh" "" >/dev/null

# ПОЛОЖИТЕЛЬНЫЙ КОНТРОЛЬ: третья правка РОДИТЕЛЯ обязана дать напоминание. Без него
# «субагенту тихо» неотличимо от «механизм онемел совсем», и проба зеленела бы на
# выпотрошенном хуке.
OUT=$(call "" "$F")
grep -q 'Переработка' <<< "$OUT" || {
    echo "probe_D453: контроль — родитель не получил напоминания, судить нечем: ${OUT:0:160}" >&2
    exit 2
}

# Суд 1: ПЕРВАЯ правка субагента той же сессии. Цепочка родителя ему не принадлежит.
OUT=$(call "" "$F" sub1)
if grep -q 'Переработка' <<< "$OUT"; then
    echo "probe_D453: дефект — первая правка субагента получила цепочку родителя" >&2
    exit 1
fi

# Суд 2: журнал субагента заведён ОТДЕЛЬНО — и заведён файловым инструментом, то есть
# веткой `Edit|Write|MultiEdit`, где актор прежде не резолвился вовсе.
[ -f "$S/rework-$SID.agent-sub1.jsonl" ] || {
    echo "probe_D453: дефект — журнал субагента не отделён (ветка Edit не резолвит актора)" >&2
    exit 1
}
[ -f "$S/rework-$SID.jsonl" ] || {
    echo "probe_D453: контроль — журнала родителя нет, судить нечем" >&2
    exit 2
}

# Суд 3: повод, накрученный СУБАГЕНТОМ, не попадает в файл, который читает родитель.
# Считается ПРИРОСТ, а не наличие: в файле родителя законно лежит его собственный повод из
# положительного контроля выше, и проверка на непустоту приняла бы его за дефект (поймано
# первым же прогоном этой пробы 18 сентября 2026).
# Субагент правит СВОЙ файл, а не тот же, что родитель. Иначе его повод совпадает с
# родительским по подписи «путь+циклы», троттл гасит запись, прироста нет — и мутант «повод
# вернулся к общему ключу» проходил бы судом незамеченным (проверено прогоном по мутанту
# 18 сентября 2026: проба давала 2 вместо 1).
G="$T/repo/g.sh"; printf 'y\n' > "$G"
( cd "$T/repo" && git add -A && git -c user.email=p@p -c user.name=p commit -qm g ) >/dev/null 2>&1
BEFORE=$(grep -c '' "$S/rework-fired-$SID.jsonl" 2>/dev/null || true)
call "bash t.sh" "" sub1 >/dev/null; call "" "$G" sub1 >/dev/null
call "bash t.sh" "" sub1 >/dev/null; call "" "$G" sub1 >/dev/null
call "bash t.sh" "" sub1 >/dev/null
OUT=$(call "" "$G" sub1)
# СУД РАНЬШЕ КОНТРОЛЯ, и порядок здесь принципиален. На мутанте «повод вернулся к общему
# ключу» сигнал субагента гасится троттлом чужой записи — контроль падает, и проба, стоявшая
# контролем вперёд, называла настоящий ДЕФЕКТ «рамкой» (код 2 вместо 1). Прирост в файле
# родителя наблюдаем независимо от того, сказал ли механизм субагенту, поэтому судим его
# первым (найдено собственным прогоном по мутанту 18 сентября 2026).
AFTER=$(grep -c '' "$S/rework-fired-$SID.jsonl" 2>/dev/null || true)
if [ "${AFTER:-0}" -ne "${BEFORE:-0}" ]; then
    echo "probe_D453: дефект — повод субагента лёг в файл повода РОДИТЕЛЯ (было $BEFORE, стало $AFTER)" >&2
    exit 1
fi
grep -q 'Переработка' <<< "$OUT" || {
    echo "probe_D453: контроль — своя цепочка субагента не сработала, судить нечем" >&2
    exit 2
}
[ -f "$S/rework-fired-$SID.agent-sub1.jsonl" ] || {
    echo "probe_D453: дефект — повод субагента не записан под его именем" >&2
    exit 1
}

# Суд 4: СВОЙ ЦИКЛ СУБАГЕНТА ЗАМЫКАЕТСЯ, когда он начал с прогона, а не с правки.
# Это самый частый порядок и он измерен: из 400 расшифровок субагентов новее 1 сентября
# 2026 файлы правили 33, и ВСЕ 33 звали Bash ДО первой правки. Первая редакция починки
# D453 заводила таким вызовом снимок мира заранее — и следующий прогон видел правку целью
# записи, поэтому `{"kind":"run"}` не попадал в журнал НИКОГДА, цикл не замыкался, и
# субагент терял сигнал переработки целиком. Ни одна из четырёх проб этого не судила
# (найдено адверсариальной проверкой 18 сентября 2026), поэтому суд заведён здесь.
S2="$T/state2"; mkdir -p "$S2"
SID2=d453b
call2() {  # call2 <команда|""> <файл|""> [agent_id]
    jq -cn --arg s "$SID2" --arg c "$1" --arg f "$2" --arg a "${3:-}" --arg w "$T/repo" \
        '{session_id:$s, cwd:$w}
         + (if $c == "" then {tool_name:"Edit", tool_input:{file_path:$f}}
            else {tool_name:"Bash", tool_input:{command:$c}} end)
         + (if $a == "" then {} else {agent_id:$a, agent_type:"general-purpose"} end)' \
      | env STATE_DIR="$S2" bash "$HOOK" 2>/dev/null
}
# ДВА прогона между правками, а не один, и это не украшение сценария. Запись
# `{"kind":"run"}` появляется ТОЛЬКО когда перечень целей ПУСТ (`rework-detector.sh:262`), а
# `rw_world_targets` объявляет целью всякий файл, чей mtime отличается от снимка прошлого
# вызова. `file_mtime` меряет ЦЕЛЫМИ секундами (`portable-lib.sh:181-126`), поэтому первый
# прогон после правки пишет `run` лишь тогда, когда правка попала с ним в одну секунду —
# по совпадению. Замер 18 сентября 2026: с одним прогоном проба краснела 3 раза из 30 на
# ЗДОРОВОМ дереве, под нагрузкой 8 из 40, а с гарантированной задержкой в секунду — 30 из 30.
# Второй прогон поглощает изменение мира в снимок, и третий пишет `run` детерминированно;
# в живой работе между правкой и прогоном тестов вызовов оболочки обычно больше одного,
# поэтому сценарий здесь ЖИЗНЕННЫЙ, а не подогнанный.
# Само ограничение механизма — счёт циклов зависит от числа вызовов Bash между правками —
# пробой не лечится и заведено отдельным пунктом долга D458.
call2 "git status" "" sub2 >/dev/null          # прогон ДО первой правки — обычный порядок
printf 'a\n' > "$F"; call2 "" "$F" sub2 >/dev/null
call2 "bash t.sh" "" sub2 >/dev/null; call2 "bash t.sh" "" sub2 >/dev/null
printf 'b\n' > "$F"; call2 "" "$F" sub2 >/dev/null
call2 "bash t.sh" "" sub2 >/dev/null; call2 "bash t.sh" "" sub2 >/dev/null
printf 'c\n' > "$F"
OUT=$(call2 "" "$F" sub2)
if ! grep -q 'Переработка' <<< "$OUT"; then
    RUNS=$(grep -c '"kind":"run"' "$S2/rework-$SID2.agent-sub2.jsonl" 2>/dev/null || true)
    echo "probe_D453: дефект — цикл субагента не замкнулся: начав с прогона, он не получает сигнала (записей run в журнале: ${RUNS:-0})" >&2
    exit 1
fi
# Суд 5: ОТСУТСТВИЕ ЧУЖОГО, а не только наличие своего. Суды выше судят, что у субагента
# СВОЙ журнал и СВОЙ повод; починка с теневой дозаписью (журнал заведён под именем актора И
# продублирован в журнал родителя) проходила их все — воспроизведено адверсариальной
# проверкой 18 сентября 2026, родитель получал «Переработку», накрученную субагентом.
# Направление «субагент → родитель» дороже обратного и потому судится отдельно.
PBEFORE=$(grep -c '' "$S/rework-$SID.jsonl" 2>/dev/null || true)
WBEFORE=$(grep -c '' "$S/rework-world-$SID.txt" 2>/dev/null || true)
H="$T/repo/h.sh"; printf 'z\n' > "$H"
( cd "$T/repo" && git add -A && git -c user.email=p@p -c user.name=p commit -qm h ) >/dev/null 2>&1
for _ in 1 2 3; do
    printf '%s\n' "$RANDOM" > "$H"; call "" "$H" sub9 >/dev/null
    call "bash t.sh" "" sub9 >/dev/null; call "bash t.sh" "" sub9 >/dev/null
done
PAFTER=$(grep -c '' "$S/rework-$SID.jsonl" 2>/dev/null || true)
if [ "${PAFTER:-0}" -ne "${PBEFORE:-0}" ]; then
    echo "probe_D453: дефект — действия субагента дописаны в журнал РОДИТЕЛЯ (было $PBEFORE, стало $PAFTER)" >&2
    exit 1
fi
[ -f "$S/rework-$SID.agent-sub9.jsonl" ] || {
    echo "probe_D453: контроль — журнал субагента sub9 не заведён, судить нечем" >&2
    exit 2
}
WAFTER=$(grep -c '' "$S/rework-world-$SID.txt" 2>/dev/null || true)
if [ "${WAFTER:-0}" -ne "${WBEFORE:-0}" ]; then
    echo "probe_D453: дефект — снимок мира РОДИТЕЛЯ переписан вызовом субагента" >&2
    exit 1
fi
exit 0
